PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS products (product_id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT, unit TEXT, current_purchase_price INTEGER NOT NULL DEFAULT 0, current_sale_price INTEGER NOT NULL DEFAULT 0, minimum_stock REAL NOT NULL DEFAULT 0, current_quantity REAL NOT NULL DEFAULT 0, stock_value INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS customers (customer_id TEXT PRIMARY KEY, name TEXT NOT NULL, mobile TEXT, address TEXT, opening_due INTEGER NOT NULL DEFAULT 0, current_due INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS suppliers (supplier_id TEXT PRIMARY KEY, name TEXT NOT NULL, mobile TEXT, address TEXT, opening_due INTEGER NOT NULL DEFAULT 0, current_due INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS purchases (purchase_id TEXT PRIMARY KEY, date TEXT NOT NULL, supplier_id TEXT, product_id TEXT NOT NULL, quantity REAL NOT NULL, unit_cost INTEGER NOT NULL, total_cost INTEGER NOT NULL, payment INTEGER NOT NULL DEFAULT 0, supplier_due INTEGER NOT NULL DEFAULT 0, payment_method TEXT, note TEXT, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT, created_by TEXT, FOREIGN KEY(supplier_id) REFERENCES suppliers(supplier_id), FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE IF NOT EXISTS sales (sale_id TEXT PRIMARY KEY, date TEXT NOT NULL, customer_id TEXT, product_id TEXT NOT NULL, quantity REAL NOT NULL, unit_sale_price INTEGER NOT NULL, total_sale INTEGER NOT NULL, unit_cost INTEGER NOT NULL, cogs INTEGER NOT NULL, payment INTEGER NOT NULL DEFAULT 0, customer_due INTEGER NOT NULL DEFAULT 0, payment_method TEXT, note TEXT, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT, created_by TEXT, FOREIGN KEY(customer_id) REFERENCES customers(customer_id), FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE IF NOT EXISTS customer_due (due_transaction_id TEXT PRIMARY KEY, date TEXT NOT NULL, customer_id TEXT NOT NULL, reference_id TEXT, description TEXT, due_added INTEGER NOT NULL DEFAULT 0, due_collection INTEGER NOT NULL DEFAULT 0, balance_after INTEGER NOT NULL DEFAULT 0, payment_method TEXT, note TEXT, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT, FOREIGN KEY(customer_id) REFERENCES customers(customer_id));
CREATE TABLE IF NOT EXISTS supplier_due (supplier_due_id TEXT PRIMARY KEY, date TEXT NOT NULL, supplier_id TEXT NOT NULL, reference_id TEXT, description TEXT, due_added INTEGER NOT NULL DEFAULT 0, payment INTEGER NOT NULL DEFAULT 0, balance_after INTEGER NOT NULL DEFAULT 0, payment_method TEXT, note TEXT, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT, FOREIGN KEY(supplier_id) REFERENCES suppliers(supplier_id));
CREATE TABLE IF NOT EXISTS expenses (expense_id TEXT PRIMARY KEY, date TEXT NOT NULL, category TEXT, description TEXT, amount INTEGER NOT NULL, payment_method TEXT, note TEXT, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT, created_by TEXT);
CREATE TABLE IF NOT EXISTS cash_transactions (cash_transaction_id TEXT PRIMARY KEY, date TEXT NOT NULL, reference_id TEXT, transaction_type TEXT NOT NULL, cash_in INTEGER NOT NULL DEFAULT 0, cash_out INTEGER NOT NULL DEFAULT 0, payment_method TEXT, description TEXT, note TEXT, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT);
CREATE TABLE IF NOT EXISTS stock_adjustments (adjustment_id TEXT PRIMARY KEY, date TEXT NOT NULL, product_id TEXT NOT NULL, system_quantity REAL NOT NULL, actual_quantity REAL NOT NULL, adjustment_quantity REAL NOT NULL, reason TEXT, unit_cost INTEGER NOT NULL DEFAULT 0, adjustment_value INTEGER NOT NULL DEFAULT 0, note TEXT, status TEXT NOT NULL DEFAULT 'Active', created_at TEXT, created_by TEXT, FOREIGN KEY(product_id) REFERENCES products(product_id));
CREATE TABLE IF NOT EXISTS daily_accounts (date TEXT PRIMARY KEY, total_sales INTEGER NOT NULL DEFAULT 0, cash_sales INTEGER NOT NULL DEFAULT 0, credit_sales INTEGER NOT NULL DEFAULT 0, customer_collection INTEGER NOT NULL DEFAULT 0, total_cogs INTEGER NOT NULL DEFAULT 0, gross_profit INTEGER NOT NULL DEFAULT 0, total_purchase INTEGER NOT NULL DEFAULT 0, purchase_payment INTEGER NOT NULL DEFAULT 0, expense INTEGER NOT NULL DEFAULT 0, net_profit INTEGER NOT NULL DEFAULT 0, expected_cash INTEGER NOT NULL DEFAULT 0, actual_cash INTEGER NOT NULL DEFAULT 0, cash_difference INTEGER NOT NULL DEFAULT 0, closing_stock_value INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'Active', updated_at TEXT);
CREATE TABLE IF NOT EXISTS system_settings (setting TEXT PRIMARY KEY, value TEXT, description TEXT);
CREATE TABLE IF NOT EXISTS audit_log (log_id TEXT PRIMARY KEY, timestamp TEXT NOT NULL, user TEXT, action TEXT, module TEXT, reference_id TEXT, field TEXT, old_value TEXT, new_value TEXT, reason TEXT, result TEXT);
CREATE INDEX IF NOT EXISTS idx_sales_date ON sales(date); CREATE INDEX IF NOT EXISTS idx_sales_product ON sales(product_id); CREATE INDEX IF NOT EXISTS idx_sales_customer ON sales(customer_id);
CREATE INDEX IF NOT EXISTS idx_purchases_date ON purchases(date); CREATE INDEX IF NOT EXISTS idx_purchases_product ON purchases(product_id); CREATE INDEX IF NOT EXISTS idx_purchases_supplier ON purchases(supplier_id);
CREATE INDEX IF NOT EXISTS idx_customer_due_customer_date ON customer_due(customer_id,date); CREATE INDEX IF NOT EXISTS idx_supplier_due_supplier_date ON supplier_due(supplier_id,date);
CREATE INDEX IF NOT EXISTS idx_cash_date ON cash_transactions(date); CREATE INDEX IF NOT EXISTS idx_audit_timestamp ON audit_log(timestamp);
